import React from "react";

export default function FloatingUploadButton({ onClick }) {
  return (
    <button
      type="button"
      onClick={onClick}
      onPointerDown={(event) => event.stopPropagation()}
      className="absolute left-4 bottom-4 z-20 inline-flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-br from-[#ff4d6d] via-[#ff2f6d] to-[#d02b5a] text-white shadow-[0_20px_60px_rgba(255,77,109,0.25)] transition duration-200 hover:scale-[1.03] focus:outline-none"
      aria-label="Upload video"
    >
      <span className="text-[26px] leading-none">+</span>
    </button>
  );
}
